@Override public void getPaymentMethods(GetPaymentMethodsRequest req, StreamObserver<GetPaymentMethodsReply> responseObserver) {
  try {
    var paymentMethods = coreApi.getFiatPaymentMethods().stream()
        .map(PaymentMethod::toProtoMessage)
        .collect(Collectors.toList());
    var reply = GetPaymentMethodsReply.newBuilder().addAllPaymentMethods(paymentMethods).build();
    responseObserver.onNext(reply);
    responseObserver.onCompleted();
  } catch (RuntimeException e) {
    // Log the exception and handle it appropriately
    responseObserver.onError(Status.INTERNAL.withDescription("An error occurred while processing payment methods").withCause(e).asRuntimeException());
  }
}
